def cycpattern_check(a , b):
    if len(b) > len(a):
        return False

    for i in range(len(a)):
        rotated_a = a[i:] + a[:i]
        if b in rotated_a:
            return True

    # Check original string as well (rotation by 0 is covered, but let's be explicit about non-rotated case)
    # Actually the loop covers all rotations including i=0 which is the original string.

    return False
